usage.code:
import { AccordionGallery } from "solen-design/react";

const items = [
  { image: "/photos/canyon.jpg", label: "Canyon", link: "#" },
  { image: "/photos/ridge.jpg", label: "Ridgeline", link: "#" },
  { image: "/photos/falls.jpg", label: "Falls", link: "#" },
  { image: "/photos/harbour.jpg", label: "Harbour", link: "#" },
  { image: "/photos/skyline.jpg", label: "Skyline", link: "#" }
];

<AccordionGallery
  items={items}
  defaultIndex={2}
  orientation="horizontal"
  trigger="hover"
  expandRatio={0.52}
  height={460}
  gap={10}
  radius={16}
  duration={0.6}
  tilt={8}
  parallax={0.5}
  grayscale={true}
  showLabels={true}
/>
